import java.util.ArrayDeque;
import java.util.Deque;

/** A bounded history of text lines; the oldest line is dropped when full. */
final class LineHistory {
    private final Deque<String> lines = new ArrayDeque<>();
    private final int capacity;

    LineHistory(int capacity) {
        if (capacity < 1) {
            throw new IllegalArgumentException("capacity must be positive");
        }
        this.capacity = capacity;
    }

    void add(String line) {
        if (lines.size() == capacity) {
            lines.removeFirst();
        }
        lines.addLast(line);
    }

    String latest() {
        return lines.isEmpty() ? "" : lines.peekLast();
    }

    int size() {
        return lines.size();
    }
}

import java.util.ArrayList;
import java.util.List;

/** Splits a text into words and keeps their order. */
final class WordSplitter {
    static List<String> split(String text) {
        List<String> words = new ArrayList<>();
        StringBuilder current = new StringBuilder();
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (Character.isLetterOrDigit(c)) {
                current.append(c);
            } else if (current.length() > 0) {
                words.add(current.toString());
                current.setLength(0);
            }
        }
        if (current.length() > 0) {
            words.add(current.toString());
        }
        return words;
    }
}

/** Immutable two-dimensional point with a few helpers. */
record Point(double x, double y) {
    static final Point ORIGIN = new Point(0, 0);

    Point translate(double dx, double dy) {
        return new Point(x + dx, y + dy);
    }

    double distanceTo(Point other) {
        double dx = x - other.x;
        double dy = y - other.y;
        return Math.sqrt(dx * dx + dy * dy);
    }

    Point midpointTo(Point other) {
        return new Point((x + other.x) / 2, (y + other.y) / 2);
    }

    boolean isOrigin() {
        return x == 0 && y == 0;
    }
}

import java.util.HashMap;
import java.util.Map;

/** Counts how often each key was seen. */
final class Counter<K> {
    private final Map<K, Integer> counts = new HashMap<>();

    void increment(K key) {
        counts.merge(key, 1, Integer::sum);
    }

    int get(K key) {
        return counts.getOrDefault(key, 0);
    }

    K mostFrequent() {
        K best = null;
        int bestCount = 0;
        for (Map.Entry<K, Integer> e : counts.entrySet()) {
            if (e.getValue() > bestCount) {
                best = e.getKey();
                bestCount = e.getValue();
            }
        }
        return best;
    }
}

/** Converts between temperature scales. */
final class Temperature {
    private final double kelvin;

    private Temperature(double kelvin) {
        this.kelvin = kelvin;
    }

    static Temperature ofCelsius(double celsius) {
        return new Temperature(celsius + 273.15);
    }

    static Temperature ofFahrenheit(double fahrenheit) {
        return ofCelsius((fahrenheit - 32) * 5 / 9);
    }

    double toCelsius() {
        return kelvin - 273.15;
    }

    double toFahrenheit() {
        return toCelsius() * 9 / 5 + 32;
    }

    boolean isBelowFreezing() {
        return toCelsius() < 0;
    }
}

import java.util.Arrays;

/** Computes simple statistics over an array of measurements. */
final class Statistics {
    static double mean(double[] values) {
        double sum = 0;
        for (double v : values) {
            sum += v;
        }
        return values.length == 0 ? Double.NaN : sum / values.length;
    }

    static double median(double[] values) {
        if (values.length == 0) {
            return Double.NaN;
        }
        double[] sorted = values.clone();
        Arrays.sort(sorted);
        int mid = sorted.length / 2;
        if (sorted.length % 2 == 1) {
            return sorted[mid];
        }
        return (sorted[mid - 1] + sorted[mid]) / 2;
    }
}

import java.util.Iterator;
import java.util.NoSuchElementException;

/** An iterator over the integers from start (inclusive) to end (exclusive). */
final class IntRange implements Iterable<Integer> {
    private final int start;
    private final int end;

    IntRange(int start, int end) {
        this.start = start;
        this.end = end;
    }

    @Override
    public Iterator<Integer> iterator() {
        return new Iterator<>() {
            private int next = start;

            @Override
            public boolean hasNext() {
                return next < end;
            }

            @Override
            public Integer next() {
                if (!hasNext()) {
                    throw new NoSuchElementException();
                }
                return next++;
            }
        };
    }
}

import java.util.ArrayList;
import java.util.List;

/** A small stack of undo steps; each step is a label. */
final class UndoStack {
    private final List<String> steps = new ArrayList<>();
    private int cursor = 0;

    void push(String label) {
        while (steps.size() > cursor) {
            steps.remove(steps.size() - 1);
        }
        steps.add(label);
        cursor++;
    }

    boolean canUndo() {
        return cursor > 0;
    }

    boolean canRedo() {
        return cursor < steps.size();
    }

    String undo() {
        return steps.get(--cursor);
    }

    String redo() {
        return steps.get(cursor++);
    }
}
